    /// <summary>Where a student sits in the special-education process — which decides what documents,
    /// evaluation case and meetings the seeder creates for them.</summary>
    public enum Track
    {
        /// <summary>On an IEP: one finalized IEP with goals and progress data.</summary>
        EstablishedIep,

        /// <summary>Just reevaluated: a finalized ETR followed by a finalized IEP.</summary>
        IepWithRecentEtr,

        /// <summary>Newly found eligible: an IEP being written right now, not yet finalized.</summary>
        DraftIep,

        /// <summary>Initial evaluation finished: consent on file, finalized ETR, eligibility determined,
        /// and the first IEP started from it.</summary>
        EvaluationEtrComplete,

        /// <summary>Initial evaluation running: referral and consent, no documents yet.</summary>
        EvaluationInProgress
    }

