    // -------------------------------------------------------------------------------------- Validation

    /// <summary>
    /// Fails fast on a roster that contradicts itself, so a future edit here is caught before a seed run
    /// touches a live database: a parent linked to the wrong child, a duplicated email, a student in a
    /// building whose grade band does not contain their grade, or a building missing staff every student
    /// there needs on their team. Called by <c>DemoSeeder.SeedAsync</c> and covered by unit tests.
    /// </summary>
    public static void Validate()
    {
        foreach (var parent in Parents)
        {
            if (parent.StudentIndex < 0 || parent.StudentIndex >= Students.Length)
                throw new InvalidOperationException($"Demo roster: parent '{parent.FirstName} {parent.LastName}' points at student index {parent.StudentIndex}, which does not exist.");
            var child = Students[parent.StudentIndex];
            if (child.LastName != parent.LastName)
                throw new InvalidOperationException($"Demo roster: parent '{parent.FirstName} {parent.LastName}' is linked to '{child.FirstName} {child.LastName}' — surnames must match so the family view reads correctly.");
        }

        if (StudentAccountStudentIndex < 0 || StudentAccountStudentIndex >= Students.Length)
            throw new InvalidOperationException($"Demo roster: the student account points at student index {StudentAccountStudentIndex}, which does not exist.");
        var studentAccount = Students[StudentAccountStudentIndex];
        if (studentAccount.FirstName != StudentAccountFirstName || studentAccount.LastName != StudentAccountLastName)
            throw new InvalidOperationException($"Demo roster: the student account is named '{StudentAccountFirstName} {StudentAccountLastName}' but student index {StudentAccountStudentIndex} is '{studentAccount.FirstName} {studentAccount.LastName}'.");

        var emails = Staff.Select(s => s.Email)
            .Concat(new[] { DistrictAdmin.Email, StudentAccountEmail })
            .Concat(Parents.Select(p => p.Email))
            .ToList();
        var duplicate = emails.GroupBy(e => e, StringComparer.OrdinalIgnoreCase).FirstOrDefault(g => g.Count() > 1);
        if (duplicate != null)
            throw new InvalidOperationException($"Demo roster: '{duplicate.Key}' is used by more than one account.");

        if (DistrictAdmin.SchoolIndex != null)
            throw new InvalidOperationException("Demo roster: a District Admin invite must not carry a school (see StaffInviteService).");

        for (var schoolIndex = 0; schoolIndex < Schools.Length; schoolIndex++)
        {
            if (!CaseManagersAt(schoolIndex).Any())
                throw new InvalidOperationException($"Demo roster: '{Schools[schoolIndex].Name}' has no Teacher to act as a case manager.");
            if (!Staff.Any(s => s.OrgRoleId == OrgRoleIds.SchoolAdmin && s.SchoolIndex == schoolIndex))
                throw new InvalidOperationException($"Demo roster: '{Schools[schoolIndex].Name}' has no School Admin to act as the LEA representative.");
            if (!Staff.Any(s => s.OrgRoleId == OrgRoleIds.GeneralEducator && s.SchoolIndex == schoolIndex))
                throw new InvalidOperationException($"Demo roster: '{Schools[schoolIndex].Name}' has no General Educator.");
        }

        foreach (var staff in Staff)
            if (staff.SchoolIndex == null || staff.SchoolIndex < 0 || staff.SchoolIndex >= Schools.Length)
                throw new InvalidOperationException($"Demo roster: '{staff.FirstName} {staff.LastName}' has no valid home building — every invited role requires one.");

        foreach (var student in Students)
        {
            if (student.SchoolIndex < 0 || student.SchoolIndex >= Schools.Length)
                throw new InvalidOperationException($"Demo roster: '{student.FirstName} {student.LastName}' is at building index {student.SchoolIndex}, which does not exist.");
            if (!GradesAt(student.SchoolIndex).Contains(student.Grade))
                throw new InvalidOperationException($"Demo roster: '{student.FirstName} {student.LastName}' is in grade {student.Grade.ToDisplay()}, which is not taught at '{Schools[student.SchoolIndex].Name}'.");
        }
    }

    /// <summary>The grades a building teaches, matching the <see cref="SchoolSpec.GradeRange"/> labels.</summary>
    public static GradeLevel[] GradesAt(int schoolIndex) => schoolIndex switch
    {
        Elementary => new[] { GradeLevel.K, GradeLevel.G1, GradeLevel.G2, GradeLevel.G3, GradeLevel.G4, GradeLevel.G5 },
        Middle => new[] { GradeLevel.G6, GradeLevel.G7, GradeLevel.G8 },
        _ => new[] { GradeLevel.G9, GradeLevel.G10, GradeLevel.G11, GradeLevel.G12 }
    };
